Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/NeZero.lean"],{"text":"/-\nCopyright (c) 2021 Eric Rodriguez. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Eric Rodriguez\n-/\nmodule\n\nprelude\npublic import Init.Data.Zero\npublic import Init.Core\n\npublic section\n\n\n/-!\n# `NeZero` typeclass\n\nWe create a typeclass `NeZero n` which carries around the fact that `(n : R) ≠ 0`.\n\n## Main declarations\n\n* `NeZero`: `n ≠ 0` as a typeclass.\n-/\n\n\nvariable {R : Type _} [Zero R]\n\n/-- A type-class version of `n ≠ 0`.  -/\nclass NeZero (n : R) : Prop where\n  /-- The proposition that `n` is not zero. -/\n  out : n ≠ 0\n\ntheorem NeZero.ne (n : R) [h : NeZero n] : n ≠ 0 :=\n  h.out\n\ntheorem NeZero.ne' (n : R) [h : NeZero n] : 0 ≠ n :=\n  h.out.symm\n\ntheorem neZero_iff {n : R} : NeZero n ↔ n ≠ 0 :=\n  ⟨fun h ↦ h.out, NeZero.mk⟩\n\n@[simp] theorem neZero_zero_iff_false {α : Type _} [Zero α] : NeZero (0 : α) ↔ False :=\n  ⟨fun _ ↦ NeZero.ne (0 : α) rfl, fun h ↦ h.elim⟩\n\ninstance {p : Prop} [Decidable p] {n m : Nat} [NeZero n] [NeZero m] :\n    NeZero (if p then n else m) := by\n  split <;> infer_instance\n\ninstance {n m : Nat} [h : NeZero n] : NeZero (n + m) where\n  out :=\n    match n, h, m with\n    | _ + 1, _, 0\n    | _ + 1, _, _ + 1 => fun h => nomatch h\n\ninstance {n m : Nat} [h : NeZero m] : NeZero (n + m) where\n  out :=\n    match m, h, n with\n    | _ + 1, _, 0 => fun h => nomatch h\n    | _ + 1, _, _ + 1 => fun h => nomatch h\n\ninstance {n m : Nat} [hn : NeZero n] [hm : NeZero m] : NeZero (n * m) where\n  out :=\n    match n, hn, m, hm with\n    | _ + 1, _, _ + 1, _ => fun h => nomatch h\n","refs":[[28,6,28,12,"0b91810ddab3",true],[32,31,32,37,"0b91810ddab3",false],[35,32,35,38,"0b91810ddab3",false],[38,29,38,35,"0b91810ddab3",false],[41,62,41,68,"0b91810ddab3",false],[41,79,41,84,"9f7dfdc52bce",false],[42,29,42,32,"4678ade8cd63",false],[42,44,42,48,"265eb2c7534b",false],[44,21,44,30,"ce632cbef893",false],[44,41,44,44,"1a9353d78c15",false],[44,47,44,53,"0b91810ddab3",false],[44,58,44,64,"0b91810ddab3",false],[45,4,45,10,"0b91810ddab3",false],[48,16,48,19,"1a9353d78c15",false],[48,26,48,32,"0b91810ddab3",false],[48,38,48,44,"0b91810ddab3",false],[54,16,54,19,"1a9353d78c15",false],[54,26,54,32,"0b91810ddab3",false],[54,38,54,44,"0b91810ddab3",false],[60,16,60,19,"1a9353d78c15",false],[60,27,60,33,"0b91810ddab3",false],[60,43,60,49,"0b91810ddab3",false],[60,55,60,61,"0b91810ddab3",false]]});
